"""Credential wiring: where the API key travels on the wire."""

import pytest
from aletheca import AlethecaSyncClient, APIError, AuthError
from bibliofabric.auth import NoAuth

from ..conftest import entity


def keyless(settings) -> AlethecaSyncClient:
    return AlethecaSyncClient(settings=settings.model_copy(update={"api_key": None}))


def test_default_scheme_sends_api_key_query_param(client, httpx_mock):
    httpx_mock.add_response(json=entity("W1"))
    client.works.get("W1")
    request = httpx_mock.get_requests()[-1]
    assert request.url.params["api_key"] == "test-key"
    assert "authorization" not in request.headers


def test_bearer_scheme_sends_authorization_header(settings, httpx_mock):
    client = AlethecaSyncClient(
        settings=settings.model_copy(update={"auth_scheme": "bearer"})
    )
    httpx_mock.add_response(json=entity("W1"))
    client.works.get("W1")
    request = httpx_mock.get_requests()[-1]
    assert request.headers["authorization"] == "Bearer test-key"
    assert "api_key" not in request.url.params


def test_keyless_client_sends_no_credential(settings, httpx_mock):
    client = keyless(settings)
    httpx_mock.add_response(json=entity("W1"))
    client.works.get("W1")
    request = httpx_mock.get_requests()[-1]
    assert "api_key" not in request.url.params
    assert "authorization" not in request.headers


def test_explicit_strategy_wins_over_key(settings, httpx_mock):
    client = AlethecaSyncClient(
        settings=settings, auth_strategy=NoAuth(), api_key="ignored"
    )
    httpx_mock.add_response(json=entity("W1"))
    client.works.get("W1")
    request = httpx_mock.get_requests()[-1]
    assert "api_key" not in request.url.params


def test_keyless_401_gets_actionable_message(settings, httpx_mock):
    httpx_mock.add_response(status_code=401, json={})
    client = keyless(settings)
    with pytest.raises(AuthError) as excinfo:
        client.works.search()
    message = str(excinfo.value)
    assert "ALETHECA_API_KEY" in message
    assert "api_key=" in message


def test_keyed_401_keeps_upstream_message(client, httpx_mock):
    httpx_mock.add_response(status_code=401, json={})
    with pytest.raises(AuthError) as excinfo:
        client.works.search()
    assert "Get a free API key" not in str(excinfo.value)


def test_error_str_redacts_credential(client, httpx_mock):
    httpx_mock.add_response(status_code=500, json={})
    with pytest.raises(APIError) as excinfo:
        client.works.search()
